  "Par groupes de quêtes (expérimental)": { en: "By quest groups (experimental)", de: "Nach Questgruppen (experimentell)", es: "Por grupos de misiones (experimental)", pt: "Por grupos de missões (experimental)", ru: "По группам заданий (экспериментально)", ko: "퀘스트 그룹별 (실험적)", zhCN: "按任务分组（实验性）", zhTW: "依任務分組（實驗性）" },
  "Par rapport au farm : 0.5 = une quête doit rapporter au moins la moitié de l'XP/heure du farm.": { en: "Compared with grinding: 0.5 = a quest must give at least half the XP/hour of grinding.", de: "Im Vergleich zum Grinden: 0,5 = eine Quest muss mindestens die Hälfte der EP/Stunde des Grindens bringen.", es: "Respecto al farmeo: 0,5 = una misión debe dar al menos la mitad de la EXP/hora del farmeo.", pt: "Em relação ao farm: 0,5 = uma missão deve render ao menos metade do XP/hora do farm.", ru: "По сравнению с гриндом: 0,5 — задание должно давать хотя бы половину опыта в час от гринда.", ko: "사냥 대비: 0.5 = 퀘스트는 사냥 시간당 경험치의 절반 이상을 줘야 합니다.", zhCN: "与刷怪相比：0.5 = 任务每小时经验至少为刷怪的一半。", zhTW: "與練怪相比：0.5 = 任務每小時經驗至少為練怪的一半。" },
  "Par rapport à un mob normal du même niveau (les élites donnent 2× l'XP).": { en: "Compared with a normal mob of the same level (elites give 2× the XP).", de: "Im Vergleich zu einem normalen Gegner gleicher Stufe (Elite gibt 2× EP).", es: "Respecto a un enemigo normal del mismo nivel (los élites dan 2× EXP).", pt: "Em relação a um inimigo normal do mesmo nível (elites dão 2× o XP).", ru: "По сравнению с обычным мобом того же уровня (элита даёт 2× опыта).", ko: "같은 레벨 일반 몹 대비 (정예는 경험치 2배).", zhCN: "与同等级普通怪相比（精英经验为 2 倍）。", zhTW: "與同等級普通怪相比（精英經驗為 2 倍）。" },
  "Parcours par zone": { en: "Route by zone", de: "Route nach Zonen", es: "Recorrido por zona", pt: "Percurso por zona", ru: "Маршрут по зонам", ko: "지역별 경로", zhCN: "按区域路线", zhTW: "依區域路線" },
  "Part d'XP des mobs en groupe de 5": { en: "Mob XP share in a group of 5", de: "EP-Anteil der Gegner in einer 5er-Gruppe", es: "Parte de EXP de enemigos en grupo de 5", pt: "Parcela de XP dos inimigos em grupo de 5", ru: "Доля опыта с мобов в группе из 5", ko: "5인 그룹 시 몹 경험치 비율", zhCN: "五人小队中的怪物经验比例", zhTW: "五人隊伍中的怪物經驗比例" },
  "Part de grands remaniements": { en: "Share of large rebuilds", de: "Anteil großer Umbauten", es: "Proporción de grandes reorganizaciones", pt: "Proporção de grandes reorganizações", ru: "Доля крупных перестроек", ko: "대규모 재구성 비율", zhCN: "大范围重排比例", zhTW: "大範圍重排比例" },
  "Part des essais qui retirent un morceau du guide (zone, tranche de niveaux, quêtes rendues trop tard) puis le reconstruisent. 0 = désactivé.": { en: "Share of tries that remove part of the guide (zone, level range, quests turned in too late) and rebuild it. 0 = off.", de: "Anteil der Versuche, die einen Teil des Guides entfernen (Zone, Stufenbereich, zu spät abgegebene Quests) und neu aufbauen. 0 = aus.", es: "Parte de los intentos que quitan un tramo de la guía (zona, rango de niveles, misiones entregadas tarde) y lo reconstruyen. 0 = desactivado.", pt: "Parte das tentativas que removem um trecho do guia (zona, faixa de níveis, missões entregues tarde) e o reconstroem. 0 = desativado.", ru: "Доля попыток, которые удаляют часть гайда (зона, диапазон уровней, поздно сданные задания) и перестраивают её. 0 = выкл.", ko: "가이드 일부(지역, 레벨 구간, 늦게 완료한 퀘스트)를 빼고 다시 구성하는 시도의 비율. 0 = 끔.", zhCN: "移除并重建部分指南（区域、等级段、过晚交付的任务）的尝试比例。0 = 关闭。", zhTW: "移除並重建部分指南（區域、等級段、過晚交付的任務）的嘗試比例。0 = 關閉。" },
  "Personnage": { en: "Character", de: "Charakter", es: "Personaje", pt: "Personagem", ru: "Персонаж", ko: "캐릭터", zhCN: "角色", zhTW: "角色" },
